INSERT INTO news (kind, title, body) VALUES
 ('update', 'Novos mapas: de Dungeon 2 a Crywolf', 'Nove mapas novos abriram em sequência de nível — Dungeon 2 (35), Atlans (45), Lost Tower (55), Dungeon 3 (65), Tarkan (75), Icarus (90), Aida (110), Kalima (130, boss Kundun) e Crywolf (150, boss Balgass) — com monstros novos e os conjuntos Tempestade, Fênix e Abismo.');
